+  KeyManagement,
+  KEY_WRAP_ALGORITHM,
+  type WrappedDataKey,
+} from "./keyManagement.js";
+
+const CONTENT_ALGORITHM = "AES-256-GCM";
+const FORMAT_VERSION = "1";
+const IV_BYTES = 12;
+const AUTH_TAG_BYTES = 16;
+
+interface EncryptionMetadata {
+  encryptionversion: string;
+  contentalgorithm: string;
+  wrapalgorithm: string;
+  keyid: string;
+  wrappedkey: string;
+  iv: string;
+  authtag: string;
+}
