+      `Unsupported content encryption algorithm "${contentAlgorithm}".`,
+      "metadata",
+    );
+  }
+  if (wrapAlgorithm !== KEY_WRAP_ALGORITHM) {
+    throw new EncryptedBlobError(
+      `Unsupported key wrap algorithm "${wrapAlgorithm}".`,
+      "metadata",
+    );
+  }
+
